46	  const filePath = path.join(config.dir, ...key.split('/'));
47	  const body = await getBlob(config.serverUrl, key);
48	  await fsp.mkdir(path.dirname(filePath), { recursive: true });
49	  await fsp.writeFile(filePath, body);
50	}
