52	/**
53	 * Bidirectionally reconciles config.dir with the server by key and sha256,
54	 * folding push and pull into one pass: a file present on only one side is
55	 * transferred to the other (local-only -> upload, server-only -> download).
56	 * A file present on both sides with differing sha256 is a candidate
57	 * conflict, resolved against MANIFEST_FILENAME's record of what was common
58	 * as of the last successful sync (absent on a first run):
59	 *   - if the manifest shows one side still matches the last-known-common
60	 *     sha256, only the other side actually changed, and that side wins
61	 *     outright (no mtime comparison needed);
62	 *   - otherwise both sides changed (or there is no manifest entry at all,
63	 *     e.g. the first sync) - the strict SYNCBOX-SPEC.md rule applies: newer
64	 *     modified_at/mtime wins, local wins ties.
65	 * Never deletes a file on either side - a key present remotely but absent
66	 * locally (even if it was synced before and only removed on one side) is
67	 * simply re-downloaded, the same as any other server-only key.
68	 */
69	async function run(config) {
70	  await fsp.mkdir(config.dir, { recursive: true });
71	  const manifestPath = path.join(config.dir, MANIFEST_FILENAME);
72	
73	  const [manifest, localFiles, remoteBlobs] = await Promise.all([
74	    readManifest(manifestPath),
75	    walkDir(config.dir),
76	    listBlobs(config.serverUrl),
77	  ]);
78	
79	  const localByKey = new Map();
80	  for (const file of localFiles) {
81	    if (file.key === MANIFEST_FILENAME) continue;
82	    const [sha256, stat] = await Promise.all([sha256File(file.filePath), fsp.stat(file.filePath)]);
83	    localByKey.set(file.key, { filePath: file.filePath, sha256, mtimeMs: stat.mtimeMs });
84	  }
85	
86	  const remoteByKey = new Map(remoteBlobs.map((blob) => [blob.key, blob]));
87	  const allKeys = new Set([...localByKey.keys(), ...remoteByKey.keys()]);
88	
89	  const uploaded = [];
90	  const downloaded = [];
91	  const unchanged = [];
92	  const newManifest = {};
93	
94	  for (const key of [...allKeys].sort()) {
95	    const local = localByKey.get(key);
96	    const remote = remoteByKey.get(key);
97	
98	    if (local && !remote) {
99	      await uploadFile(config, key, local);
100	      uploaded.push(key);
101	      newManifest[key] = local.sha256;
102	      continue;
103	    }
104	
105	    if (!local && remote) {
106	      await downloadFile(config, key);
107	      downloaded.push(key);
108	      newManifest[key] = remote.sha256;
109	      continue;
110	    }
111	
112	    if (local.sha256 === remote.sha256) {
113	      unchanged.push(key);
114	      newManifest[key] = local.sha256;
115	      continue;
116	    }
117	
118	    const baseSha256 = manifest[key];
119	    let winner;
120	    if (baseSha256 !== undefined && baseSha256 === local.sha256) {
121	      winner = 'remote'; // local untouched since last sync, so only remote changed
122	    } else if (baseSha256 !== undefined && baseSha256 === remote.sha256) {
123	      winner = 'local'; // remote untouched since last sync, so only local changed
124	    } else {
125	      const remoteMs = Date.parse(remote.modified_at);
126	      winner = local.mtimeMs >= remoteMs ? 'local' : 'remote';
127	    }
128	
129	    if (winner === 'local') {
130	      await uploadFile(config, key, local);
131	      uploaded.push(key);
132	      newManifest[key] = local.sha256;
133	    } else {
134	      await downloadFile(config, key);
135	      downloaded.push(key);
136	      newManifest[key] = remote.sha256;
137	    }
138	  }
139	
140	  await fsp.writeFile(manifestPath, JSON.stringify(newManifest, null, 2));
141	
142	  return { uploaded, downloaded, unchanged };
143	}
144	
145	module.exports = { run, MANIFEST_FILENAME };
